<?php
require_once dirname(__DIR__).'/app/views.php'; $u=require_role(['customer','staff','admin']); $error=null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    try {
        $id=integer_input('booking_id',1,PHP_INT_MAX);
        $s=sql("UPDATE bookings SET status='cancelled' WHERE id=? AND user_id=? AND status IN ('pending','confirmed') AND travel_date>=?",[$id,$u['id'],date('Y-m-d')]);
        if (!$s->rowCount()) throw new InvalidArgumentException('This booking cannot be cancelled. Please contact our team.');
        flash('Your booking has been cancelled.'); go('/dashboard.php');
    } catch (InvalidArgumentException $ex) {$error=$ex->getMessage();}
}
$bookings=sql('SELECT b.*,p.destination FROM bookings b JOIN tour_packages p ON p.id=b.package_id WHERE b.user_id=? ORDER BY b.id DESC',[$u['id']])->fetchAll();
page_start('Your dashboard'); heading(strtoupper($u['role']).' PORTAL','Hello, '.$u['name'].'.','Your journeys, all in one place.'); ?>
<section class="container pb-5"><?php dashboard_nav('Overview'); error_box($error); ?>
<?php if ($u['role']!=='customer'): $stats=sql("SELECT COUNT(*) AS total,COALESCE(SUM(status='pending'),0) AS pending,COALESCE(SUM(status='confirmed'),0) AS confirmed FROM bookings")->fetch(); ?><div class="stats-grid"><div class="stat"><span>Total bookings</span><strong><?= (int)$stats['total'] ?></strong></div><div class="stat"><span>Awaiting review</span><strong><?= (int)$stats['pending'] ?></strong></div><div class="stat"><span>Confirmed trips</span><strong><?= (int)$stats['confirmed'] ?></strong></div></div><div class="surface"><h2>Your workspace</h2><p>Review new bookings, keep adventures up to date and help travellers plan their trips.</p><a class="btn btn-primary" href="/staff/bookings.php">Review bookings →</a> <a class="btn btn-outline-dark" href="/staff/queries.php">Answer enquiries</a></div><?php else: ?><div class="section-top mb-4"><h2>Your adventures</h2><a class="btn btn-primary" href="/packages.php">Find your next trip ↗</a></div><?php if (!$bookings): ?><div class="empty-state"><span class="feature-icon">⌖</span><h2>Your story is still unfolding.</h2><p>Your booked adventures will appear here. Ready to find the first one?</p><a class="btn btn-primary" href="/packages.php">Explore adventures</a></div><?php else: ?><div class="table-responsive surface"><table class="table align-middle"><thead><tr><th>Adventure</th><th>Travel date</th><th>Travellers</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($bookings as $b): ?><tr><td><small class="muted">GT-<?= str_pad((string)$b['id'],5,'0',STR_PAD_LEFT) ?></small><br><strong><?= e($b['package_title']) ?></strong><br><small><?= e($b['destination']) ?></small></td><td><?= e($b['travel_date']) ?></td><td><?= (int)$b['travellers'] ?></td><td><?= money($b['total_cents']) ?></td><td><?= status_badge($b['status']) ?></td><td><?php if (in_array($b['status'],['pending','confirmed'],true) && $b['travel_date']>=date('Y-m-d')): ?><form method="post" data-confirm="Cancel this booking? This action cannot be undone."><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$b['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Cancel</button></form><?php else: ?><span class="muted">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php endif; ?></section>
<?php page_end(); ?>
